<?php ob_start(); ?><h1><?= e(t('Signature #:id', ['id'=>$signature['id']??''])) ?></h1><?php if(!$signature): ?><p><?= e(t('Not found.')) ?></p><?php else: ?><div class="card"><p><b><?= e(t('Name:')) ?></b> <?= e($signature['name']) ?> <b><?= e(t('Risk:')) ?></b> <?= e(t($signature['risk'])) ?> <b><?= e(t('Source:')) ?></b> <?= e($signature['source']) ?></p><p><?= e($signature['description']) ?></p><pre><?= e(json_encode(json_decode($signature['pattern_json']?:'{}', true), JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre><form method="post" action="/signatures/test"><input type="hidden" name="id" value="<?= e($signature['id']) ?>"><input class="input" name="file_path" placeholder="<?= e(t('File path')) ?>"><button class="btn"><?= e(t('Test against file')) ?></button></form><?php if(isset($test)): ?><pre><?= e(json_encode($test, JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre><?php endif ?><form method="post" action="/signatures/sweep" onsubmit="return confirm(<?= e(json_encode(t('Check every already-scanned site for this exact signature right now? This reads every matching-extension file on the server and may take a while on a large server.'))) ?>)"><input type="hidden" name="id" value="<?= e($signature['id']) ?>"><button class="btn danger"><?= e(t('Sweep whole server for this signature now')) ?></button></form><?php if(isset($_GET['sweep_error'])): ?><p style="color:#fca5a5"><?= e(t('Sweep failed:')) ?> <?= e($_GET['sweep_error']) ?></p><?php elseif(isset($_GET['sweep_matches'])): ?><p style="color:#4ade80"><?= e(t('Sweep complete: :sites site(s), :files file(s) checked, :matches match(es) found.', ['sites'=>$_GET['sweep_sites']??0,'files'=>$_GET['sweep_files']??0,'matches'=>$_GET['sweep_matches']])) ?></p><?php endif ?></div><div class="card"><h2><?= e(t('Recent matches')) ?></h2><table><?php foreach($matches as $m): ?><tr><td><a href="/findings/<?= e($m['id']) ?>">#<?= e($m['id']) ?></a></td><td><?= e(t($m['risk'])) ?></td><td><code><?= e($m['path']) ?></code></td></tr><?php endforeach ?></table></div><?php endif ?><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>